/**
 * Client-side type augmentation for tRPC-inferred detail types.
 *
 * Several pages read `areaManagerApprovedAt`, `regionManagerApprovedAt`,
 * `financeManagerApprovedAt`, and `directorApprovedAt` from the detail
 * responses of the `actionProgram` and `eventProposal` routers. The
 * server currently does not select or expose those columns on the
 * detail procedure, but the UI is built to read them and render an
 * approval timeline. Until the server-side schema is updated to surface
 * those fields, this module-augmentation file lets the client type-check
 * the existing usage without requiring per-call `as any` casts.
 *
 * The fields are added with `Date | null` to match the Prisma column
 * shape once the server starts selecting them; existing server data
 * (where they are simply absent) will resolve to `undefined` at runtime,
 * which the call sites already guard against with `?? null` / `&&` checks.
 */
import "@trpc/server";

declare module "../../../server/src/router" {
  // Helper: every detail record gets the four approval timestamp fields
  // optional. We merge by intersecting the existing return types.
  // (We use a conditional type so we don't conflict with the existing
  // type generated by tRPC.)
  // eslint-disable-next-line @typescript-eslint/no-empty-object-type
  type _Augment<T> = T extends object
    ? T & {
        areaManagerApprovedAt?: Date | null;
        regionManagerApprovedAt?: Date | null;
        financeManagerApprovedAt?: Date | null;
        directorApprovedAt?: Date | null;
      }
    : T;
}

export {};
